<script setup lang="ts">
import { Pencil, Trash2, UsersRound, UserRound, LoaderCircle, Flame } from "lucide-vue-next";
import { locationApi } from "~/api/location";
import { companyApi } from "~/api/company";
import { organizationApi } from "~/api/organization";
import { storeToRefs } from "pinia";
import { useLocationOperationalAreaStore } from "~/stores/locationOperationalArea";
import CompanyCreateModal from "./CompanyCreateModal.vue";
import ConfirmationModal from "~/components/ConfirmationModal.vue";
import AssignExpertDrawer from "~/components/locations/AssignExpertDrawer.vue";
import EquipmentDrawer from "~/components/locations/EquipmentDrawer.vue";

type CompanyPhoto={id:number;photoUrl:string}; type CompanyRow={id:number;name:string;logo:string;photos:CompanyPhoto[];operationalRegionId:number|null;nace:string;dangerClass:string;sgk:string;status:"active"|"passive";businessEntityId?:number;brandId?:number|null}; type OperationalArea={id:number;name:string};
const route=useRoute(); const locationId=computed(()=>Number(route.params.locationId)); const tenantId=computed(()=>Number(route.params.tenantId)); const operationalAreaStore=useLocationOperationalAreaStore(); const {areas:operationalAreas}=storeToRefs(operationalAreaStore);
const emit=defineEmits<{created:[company:CompanyRow]}>(); const showCompanyModal=ref(false); const showDeleteConfirmation=ref(false); const selectedCompany=ref<CompanyRow|null>(null); const editCompany=ref<{group:string;company:string;area:string;nace:string;dangerClass:string;sgk:string;brandId?:number|null;photos?:CompanyPhoto[]}|null>(null); const saving=ref(false); const editLoading=ref(false); const updatingId=ref<number|null>(null); const loading=ref(false); const optionsLoading=ref(false); const error=ref(""); const groups=ref<{id:number;name:string}[]>([]); const companies=ref<{id:number;name:string;groupId:number|null;businessEntityId:number|null;brands:{id:number;name:string;logo_url?:string|null}[]}[]>([]); const attachedCompanies=ref<CompanyRow[]>([]);
const search=ref(""); const statusFilter=ref<"all"|"active"|"passive">("all"); const currentPage=ref(1); const perPage=ref(10);
const companyInitials=(name:string)=>name.trim().split(/\s+/).filter(Boolean).slice(0,2).map(x=>x.charAt(0).toLocaleUpperCase("tr-TR")).join("");
const showAssignExpertDrawer=ref(false); const assignExpertEntity=ref<{id:number;label:string}|null>(null);
const openAssignExpert=(company:CompanyRow)=>{assignExpertEntity.value={id:company.id,label:company.name};showAssignExpertDrawer.value=true};
const showEquipmentDrawer=ref(false); const equipmentEntity=ref<{id:number;label:string}|null>(null);
const openEquipment=(company:CompanyRow)=>{equipmentEntity.value={id:company.id,label:company.name};showEquipmentDrawer.value=true};
const areaName=(regionId:number|null)=>operationalAreas.value.find(a=>a.id===regionId)?.name||"";
const filteredCompanies=computed(()=>{const t=search.value.trim().toLocaleLowerCase("tr-TR");return attachedCompanies.value.filter(x=>(!t||`${x.name} ${areaName(x.operationalRegionId)} ${x.nace} ${x.dangerClass} ${x.sgk}`.toLocaleLowerCase("tr-TR").includes(t))&&(statusFilter.value==="all"||x.status===statusFilter.value))}); const totalPages=computed(()=>Math.max(1,Math.ceil(filteredCompanies.value.length/perPage.value))); const paginated=computed(()=>filteredCompanies.value.slice((currentPage.value-1)*perPage.value,currentPage.value*perPage.value)); const visiblePages=computed(()=>Array.from({length:Math.min(5,totalPages.value)},(_,i)=>Math.min(Math.max(1,currentPage.value-2)+i,totalPages.value)).filter((p,i,a)=>a.indexOf(p)===i));
const resetFilters=()=>{search.value="";statusFilter.value="all"}; watch([search,statusFilter,perPage],()=>currentPage.value=1);
const fetchCompanies=async()=>{const [entities]=await Promise.all([locationApi.businessEntities(locationId.value),operationalAreaStore.fetchAreas(locationId.value)]);attachedCompanies.value=entities.filter(x=>x.type==="company").map(x=>{const brand=x.pivot?.brands?.[0];return{id:x.pivot?.id??x.id,name:x.company?.name||x.name,logo:brand?.logo_url||"",photos:(x.pivot?.photos||[]).map(p=>({id:p.id,photoUrl:p.photo_url})),operationalRegionId:x.pivot?.operational_region_id??null,nace:x.pivot?.nace_code||"",dangerClass:x.pivot?.hazard_class||"",sgk:x.pivot?.sgk_workplace_number||"",status:x.pivot?.is_active===false?"passive":"active" as const,businessEntityId:x.id,brandId:brand?.id??null}})};
const loadCompanies=async()=>{if(!locationId.value)return;loading.value=true;error.value="";try{await fetchCompanies()}catch(e:any){error.value=e?.data?.message||e?.message||"Firmalar yüklenemedi."}finally{loading.value=false}};
const loadOptions=async()=>{optionsLoading.value=true;error.value="";try{const [orgs,companyList]=await Promise.all([organizationApi.listForTenant(tenantId.value),companyApi.list()]);groups.value=orgs.filter(x=>x.type==="group").map(x=>({id:x.id,name:x.name}));companies.value=companyList.map(x=>({id:x.id,name:x.name,groupId:x.organizations?.find(o=>groups.value.some(g=>g.id===o.id))?.id||null,businessEntityId:x.business_entity_id??null,brands:x.brands||[]}))}catch(e:any){error.value=e?.data?.message||e?.message||"Grup ve firma seçenekleri yüklenemedi."}finally{optionsLoading.value=false}};
const openCreate=async()=>{error.value="";selectedCompany.value=null;editCompany.value=null;showCompanyModal.value=true;if(!groups.value.length||!companies.value.length)await loadOptions()};
const addCompany=async(p:{group:string;company:string;companyId?:number;area:string;areaId?:number;nace:string;dangerClass:string;sgk:string;brandId?:number|null;photos:File[];removePhotoIds:number[]})=>{if(!locationId.value||!p.companyId)return;saving.value=true;error.value="";try{const selected=companies.value.find(x=>x.id===p.companyId);if(!selected?.businessEntityId){error.value="Seçilen Business Entity bulunamadı.";return}await locationApi.createBusinessEntity(locationId.value,{business_entity_id:selected.businessEntityId,operational_region_id:p.areaId||null,nace_code:p.nace,hazard_class:p.dangerClass,sgk_workplace_number:p.sgk,brand_ids:p.brandId?[p.brandId]:[],photos:p.photos});await fetchCompanies();showCompanyModal.value=false;const addedRow=attachedCompanies.value.find(x=>x.businessEntityId===selected.businessEntityId&&x.operationalRegionId===(p.areaId??null));if(addedRow)emit("created",addedRow)}catch(e:any){error.value=e?.data?.message||e?.message||"Firma eklenemedi."}finally{saving.value=false}};
const openEdit=async(company:CompanyRow)=>{if(editLoading.value||saving.value)return;error.value="";editLoading.value=true;selectedCompany.value=company;try{if(!groups.value.length||!companies.value.length)await loadOptions();const option=companies.value.find(x=>x.businessEntityId===company.businessEntityId);const group=groups.value.find(x=>x.id===option?.groupId);editCompany.value={group:group?.name||"",company:option?.name||company.name,area:areaName(company.operationalRegionId),nace:company.nace,dangerClass:company.dangerClass,sgk:company.sgk,brandId:company.brandId,photos:company.photos};showCompanyModal.value=true;}finally{editLoading.value=false}};
async function saveEdit(p:{group:string;company:string;companyId?:number;area:string;areaId?:number;nace:string;dangerClass:string;sgk:string;brandId?:number|null;photos:File[];removePhotoIds:number[]}){if(!selectedCompany.value)return;const pivotId=selectedCompany.value.id;showCompanyModal.value=false;selectedCompany.value=null;editCompany.value=null;updatingId.value=pivotId;error.value="";try{await locationApi.updateBusinessEntity(locationId.value,pivotId,{operational_region_id:p.areaId||null,nace_code:p.nace,hazard_class:p.dangerClass,sgk_workplace_number:p.sgk,brand_ids:p.brandId?[p.brandId]:[],photos:p.photos,remove_photo_ids:p.removePhotoIds});await fetchCompanies()}catch(e:any){error.value=e?.data?.message||e?.message||"Firma güncellenemedi."}finally{updatingId.value=null}}
function deleteCompany(company:CompanyRow){if(saving.value||editLoading.value)return;selectedCompany.value=company;showDeleteConfirmation.value=true}
const deleteConfirmationMessage=computed(()=>selectedCompany.value?`"${selectedCompany.value.name}" firmasını bu lokasyondan kaldırmak istediğinize emin misiniz?`:'Firma ilişkisini silmek istediğinize emin misiniz?');
async function confirmDeleteCompany(){if(!selectedCompany.value)return;saving.value=true;error.value="";const pivotId=selectedCompany.value.id;try{await locationApi.removeBusinessEntity(locationId.value,pivotId);const index=attachedCompanies.value.findIndex(x=>x.id===pivotId);if(index!==-1)attachedCompanies.value.splice(index,1);showDeleteConfirmation.value=false;selectedCompany.value=null}catch(e:any){error.value=e?.data?.message||e?.message||"Firma ilişkisi silinemedi."}finally{saving.value=false}}
onMounted(loadCompanies);defineExpose({openCreate,load:loadCompanies});
</script>
<template><div>
<div v-if="error" class="mb-3 rounded-lg bg-error-50 px-3 py-2 text-sm text-error-600">{{error}}</div><div v-if="loading" class="py-12 text-center text-sm text-gray-500">Yükleniyor...</div><template v-else><section class="mb-5 rounded-xl border border-gray-200 bg-white p-4 shadow-theme-xs"><div class="grid grid-cols-1 gap-3 md:grid-cols-[minmax(220px,1.2fr)_1fr_auto] md:items-center"><div class="relative"><input v-model="search" type="search" placeholder="Firma ara..." class="h-11 w-full rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none" /></div><div class="relative"><select v-model="statusFilter" class="h-11 w-full appearance-none rounded-lg border border-gray-200 bg-white px-3 pr-9 text-sm"><option value="all">Tümü</option><option value="active">Aktif</option><option value="passive">Pasif</option></select></div><button class="inline-flex h-11 items-center justify-center gap-2 rounded-lg border border-gray-200 bg-white px-4 text-sm font-medium text-gray-600" @click="resetFilters">Filtreleri Temizle</button></div></section><section class="flex w-full flex-col overflow-hidden rounded-xl border border-gray-200 bg-white shadow-theme-xs"><div class="overflow-x-auto"><table class="w-full min-w-[1080px] text-left"><thead class="border-b border-gray-100 bg-gray-50/70"><tr><th class="px-4 py-4 text-xs font-medium text-gray-500">Firma</th><th class="px-4 py-4 text-xs font-medium text-gray-500">Şube Fotoğrafı</th><th class="px-4 py-4 text-xs font-medium text-gray-500">Operasyonel Alan</th><th class="px-4 py-4 text-xs font-medium text-gray-500">NACE Kodu</th><th class="px-4 py-4 text-xs font-medium text-gray-500">Tehlike Sınıfı</th><th class="px-4 py-4 text-xs font-medium text-gray-500">SGK Sicil No</th><th class="px-4 py-4 text-xs font-medium text-gray-500">Durum</th><th class="px-4 py-4 text-right text-xs font-medium text-gray-500">İşlemler</th></tr></thead><tbody class="divide-y divide-gray-100"><tr v-for="company in paginated" :key="company.id" :class="{'opacity-60':company.id===updatingId}"><td class="px-4 py-4"><div class="flex items-center gap-3"><div class="flex h-9 w-9 items-center justify-center overflow-hidden rounded-full border border-gray-200 bg-white p-1.5"><img v-if="company.logo" :src="company.logo" :alt="company.name" class="h-full w-full object-contain"/><span v-else class="text-xs font-semibold text-gray-500">{{companyInitials(company.name)}}</span></div><span class="text-sm font-semibold text-gray-800">{{company.name}}</span></div></td><td class="px-4 py-4"><div v-if="company.photos.length" class="relative h-10 w-10"><div class="h-10 w-10 overflow-hidden rounded-lg border border-gray-200"><img :src="company.photos[0].photoUrl" :alt="company.name" class="h-full w-full object-cover"/></div><span v-if="company.photos.length>1" class="absolute -right-1.5 -top-1.5 flex h-4.5 min-w-4.5 items-center justify-center rounded-full bg-brand-500 px-1 text-[10px] font-semibold text-white">+{{company.photos.length-1}}</span></div><span v-else class="text-xs text-gray-400">—</span></td><td class="px-4 py-4 text-sm text-gray-500">{{areaName(company.operationalRegionId)||"—"}}</td><td class="px-4 py-4 text-sm text-gray-500">{{company.nace}}</td><td class="px-4 py-4"><DangerClassBadge :danger-class="company.dangerClass"/></td><td class="px-4 py-4 text-sm text-gray-500">{{company.sgk}}</td><td class="px-4 py-4"><span class="inline-flex items-center gap-1.5 rounded-full bg-success-50 px-2.5 py-1 text-xs font-medium text-success-600"><span class="h-1.5 w-1.5 rounded-full bg-success-500"/>Aktif</span></td><td class="px-4 py-4 text-right"><div v-if="company.id===updatingId" class="inline-flex items-center justify-end gap-2 pr-1"><span class="h-5 w-5 animate-spin rounded-full border-2 border-gray-200 border-t-brand-500" role="status" aria-label="Güncelleniyor"/></div><div v-else class="inline-flex items-center justify-end gap-2"><button :disabled="saving||editLoading" title="Düzenle" class="flex h-9 w-9 items-center justify-center rounded-lg border border-gray-200 text-gray-600 disabled:opacity-50" @click="openEdit(company)"><LoaderCircle v-if="editLoading&&selectedCompany?.businessEntityId===company.businessEntityId" :size="15" class="animate-spin"/><Pencil v-else :size="15"/></button><button :disabled="saving||editLoading" title="Sil" class="flex h-9 w-9 items-center justify-center rounded-lg border border-gray-200 text-error-600 disabled:opacity-50" @click="deleteCompany(company)"><Trash2 :size="15"/></button><button :disabled="saving||editLoading" title="Uzman Ata" class="flex h-9 w-9 items-center justify-center rounded-lg border border-gray-200 text-gray-600 disabled:opacity-50" @click="openAssignExpert(company)"><UsersRound :size="16"/></button><button :disabled="saving||editLoading" title="Ekipmanlar" class="flex h-9 w-9 items-center justify-center rounded-lg border border-gray-200 text-error-600 disabled:opacity-50" @click="openEquipment(company)"><Flame :size="15"/></button></div></td></tr><tr v-if="!paginated.length"><td colspan="8" class="px-4 py-12 text-center text-sm text-gray-500">Kayıt bulunamadı.</td></tr></tbody></table></div><div class="flex w-full flex-col gap-3 border-t border-gray-100 px-4 py-4 sm:flex-row sm:items-center sm:justify-between"><span class="text-sm text-gray-500">Toplam {{filteredCompanies.length}} kayıt</span><div class="flex items-center gap-1"><button class="h-9 w-9 rounded-lg border disabled:opacity-40" :disabled="currentPage===1" @click="currentPage--">‹</button><button v-for="page in visiblePages" :key="page" class="h-9 min-w-9 rounded-lg px-2 text-sm" :class="page===currentPage?'bg-brand-500 text-white':'text-gray-600'" @click="currentPage=page">{{page}}</button><button class="h-9 w-9 rounded-lg border disabled:opacity-40" :disabled="currentPage===totalPages" @click="currentPage++">›</button></div><select v-model.number="perPage" class="h-9 rounded-lg border border-gray-200 px-3 text-sm"><option :value="10">10 / sayfa</option><option :value="25">25 / sayfa</option><option :value="50">50 / sayfa</option></select></div></section></template>
<CompanyCreateModal v-model="showCompanyModal" :groups="groups" :companies="companies" :areas="operationalAreas" :loading="optionsLoading" :edit-company="editCompany" @save="selectedCompany ? saveEdit($event) : addCompany($event)"/>
<ConfirmationModal v-model:open="showDeleteConfirmation" title="Firma ilişkisini sil" :message="deleteConfirmationMessage" confirm-text="Sil" cancel-text="Vazgeç" :loading="saving" @confirm="confirmDeleteCompany"/>
<AssignExpertDrawer v-model="showAssignExpertDrawer" :entity-id="assignExpertEntity?.id ?? null" :entity-label="assignExpertEntity?.label"/>
<EquipmentDrawer v-model="showEquipmentDrawer" :entity-id="equipmentEntity?.id ?? null" :entity-label="equipmentEntity?.label"/>
</div></template>
